     <div className="table-wrap"><table><thead><tr><th>Employee / Hire Date</th><th>Verified Basic</th><th>Simulated Basic</th><th>Total Eligible Basic</th><th>13th-Month Estimate</th><th>Status</th><th>Action</th></tr></thead><tbody>{employees.map(p=>{const e=annualEstimates.find(x=>x.employeeId===p.id);const r=cfg.thirteenthReviews.find(x=>x.employeeId===p.id&&x.year===year);const stale=!!(r&&e&&Math.abs(r.eligibleBasic-e.eligibleBasic)>.005);return <tr key={p.id}><td><b>{p.name}</b><small>{p.id} · Hired {formatDay(p.hire)}</small></td><td>{e?money(e.verifiedBasic):"—"}</td><td>{e?money(e.simulatedBasic):"—"}</td><td>{e?money(e.eligibleBasic):"—"}</td><td><b>{e?money(e.amount):"—"}</b></td><td><span className="tag">{stale?"Re-review Required":r?.status||"Estimate Only"}</span></td><td><button type="button" className="secondary" onClick={()=>{setReviewEmployee(p.id);setThirteenthNotes(r?.notes||"")}}>Review</button></td></tr>})}</tbody></table></div>
