                {payslipActionMenu==="print"&&<div className="uc-payslip-menu" role="menu"><button type="button" role="menuitem" onClick={()=>{setPaper("A4");previewPayslip(release,"A4");setPayslipActionMenu(null)}}>Print / Save PDF · A4</button><button type="button" role="menuitem" onClick={()=>{setPaper("Letter");previewPayslip(release,"Letter");setPayslipActionMenu(null)}}>Print / Save PDF · Letter</button></div>}
